parameters.functionCode:
// Extract lead data from Supabase Edge Function payload contract
const body = items[0].json.body || items[0].json;
const lead = body.lead || body.data || body;

// Format international phone number (E.164 without plus for wacrm/Meta API)
let phone = String(lead.phone || '').replace(/\D/g, '');
if (phone.length === 10) {
  phone = '91' + phone;
}

// Pre-formatted message body parameters for wacrm template
return [{
  json: {
    to_phone: phone,
    template_name: 'digireach_site_visit_confirmed',
    language_code: 'en',
    customer_name: lead.name,
    project_name: lead.project || 'Digireach Lumina Towers',
    project_type: (lead.project_type || 'residential').toUpperCase(),
    unit_preference: lead.unit_preference || '3 BHK Royal Residence',
    visit_date: lead.date,
    visit_time: lead.time,
    visit_mode: lead.visit_mode || 'In-Person Executive Escort',
    location_pin_url: 'https://maps.google.com/?q=11.0016,76.9744',
    site_contact_phone: '+919876543210',
    brochure_pdf_url: 'https://digireachestates.com/brochures/' + (lead.project || 'lumina-towers').toLowerCase().replace(/\s+/g, '-') + '.pdf'
  }
}];

